% Generated by lang/stralog/tests/mkiso.py: v(Name, Expected, Goal).

:- dynamic(foo/1).
foo(1).
foo(2).
foo(3).
elk(X) :- moose(X).
:- dynamic(insect/1).
insect(ant).
insect(bee).
:- dynamic(a/1).
a(1).
a(2).
a(X) :- b(X).
b(3).
:- dynamic(c/2).
c(1, a).
c(1, 'A').
c(2, b).
c(2, 'B').

v(iso_retractall_1_01, true({current_predicate(foo/1)}), (retractall(foo(_)))).
v(iso_retractall_1_02, true, (retractall(insect(bee)))).
v(iso_retractall_1_03, true, (retractall(insect(_)))).
v(iso_retractall_1_04, true, (retractall(insect(spider)))).
v(lgt_retractall_1_08, true, (retractall(a(_)), \+ a(_))).
v(lgt_retractall_1_09, true(L == [b,'B']), (retractall(c(1, _)), findall(X, c(_, X), L))).
v(eclipse_retractall_1_10, true(I == beetle(stag)), (assertz(insect(fly(house))), assertz(insect(beetle(stag))), assertz(insect(fly(fruit))), retractall(insect(fly(_))), \+ insect(fly(_)), insect(I))).
v(eclipse_retractall_1_11, true, (retractall(mammal(_)))).
